#include <vector>
#include <set>
#include <map>
using namespace std;

class Solution {
public:
    vector<vector<int>> friendsWithNoMutual(vector<vector<int>>& Friends) {
        set<pair<int,int>> E;
        for (auto& f : Friends) { E.insert({f[0], f[1]}); E.insert({f[1], f[0]}); }
        map<int, vector<int>> adj;
        for (auto& [a, b] : E) adj[a].push_back(b);
        vector<vector<int>> ans;
        for (auto& f : Friends) {
            int a = f[0], b = f[1];
            bool ok = true;
            for (int x : adj[a]) if (x != a && x != b)
                if (binary_search(adj[b].begin(), adj[b].end(), x)) { ok = false; break; }
            if (ok) ans.push_back(f);
        }
        sort(ans.begin(), ans.end());
        return ans;
    }
};

