import java.util.*;

class Solution {
    public List<List<Integer>> friendsWithNoMutual(int[][] Friends) {
        Set<Long> E = new HashSet<>();
        Map<Integer, List<Integer>> adj = new HashMap<>();
        for (int[] f : Friends) {
            E.add(key(f[0], f[1])); E.add(key(f[1], f[0]));
            adj.computeIfAbsent(f[0], k -> new ArrayList<>()).add(f[1]);
            adj.computeIfAbsent(f[1], k -> new ArrayList<>()).add(f[0]);
        }
        List<List<Integer>> ans = new ArrayList<>();
        for (int[] f : Friends) {
            boolean ok = true;
            for (int x : adj.get(f[0]))
                if (x != f[0] && x != f[1] && adj.getOrDefault(f[1], List.of()).contains(x)) { ok = false; break; }
            if (ok) ans.add(Arrays.asList(f[0], f[1]));
        }
        ans.sort(Comparator.<List<Integer>>comparingInt(l -> l.get(0)).thenComparingInt(l -> l.get(1)));
        return ans;
    }
    private long key(int a, int b) { return ((long) a << 32) | b; }
}

