var friendsWithNoMutual = function(Friends) {
    const E = new Set();
    const adj = new Map();
    const add = (a, b) => {
        E.add(a + ',' + b);
        if (!adj.has(a)) adj.set(a, []);
        adj.get(a).push(b);
    };
    for (const [a, b] of Friends) { add(a, b); add(b, a); }
    const ans = [];
    for (const [a, b] of Friends) {
        let ok = true;
        for (const x of adj.get(a)) {
            if (x !== a && x !== b && adj.has(b) && adj.get(b).includes(x)) { ok = false; break; }
        }
        if (ok) ans.push([a, b]);
    }
    ans.sort((p, q) => p[0] - q[0] || p[1] - q[1]);
    return ans;
};

